      await act(async () => {
        await vi.advanceTimersByTimeAsync(TERMINAL_RECONNECT_DELAY_MS);
      });

      expect(openRuntimeTerminalMock).toHaveBeenCalledTimes(2);
    } finally {
      vi.useRealTimers();
    }
  });

