    ["desktop-hosted", { location: "hosted" } as const],
  ])("keeps direct file downloads for %s runtimes", async (label, runtime) => {
    if (label === "desktop-hosted") {
      Object.defineProperty(window, "yinshiDesktop", {
        configurable: true,
        value: {},
